import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-03-08","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-03-08","date":"2022-03-08T00:00:00.000Z","updated":"2022-03-09T00:00:00.000Z","tags":["Ceph","分布式存储","版本降级","NF","系统稳定性"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-03-08.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-03-08.md","lastUpdated":1780459816000}'),r={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-03-08.md"};function o(n,e,s,h,p,d){return t(),l("div",null,[...e[0]||(e[0]=[i('<p>Ceph Orchestrator Meeting 2022-03-08 会议纪要如下：</p><h3 id="会议主题-ceph版本降级支持与nfs相关问题讨论" tabindex="-1">会议主题：Ceph版本降级支持与NFS相关问题讨论 <a class="header-anchor" href="#会议主题-ceph版本降级支持与nfs相关问题讨论" aria-label="Permalink to &quot;会议主题：Ceph版本降级支持与NFS相关问题讨论&quot;">​</a></h3><h3 id="会议时间-具体时间" tabindex="-1">会议时间：具体时间 <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：具体时间&quot;">​</a></h3><h3 id="参会人员-具体人员名单" tabindex="-1">参会人员：具体人员名单 <a class="header-anchor" href="#参会人员-具体人员名单" aria-label="Permalink to &quot;参会人员：具体人员名单&quot;">​</a></h3><h3 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h3><ol><li><p><strong>版本降级支持讨论</strong></p><ul><li>讨论了Ceph版本降级支持的历史和现状，特别是minor版本降级的可行性和存在的问题。</li><li>主要问题包括迁移处理问题和升级状态问题。</li><li>结果表明，是否继续支持minor版本降级存在争议，建议在minor版本发布前进行测试，并尝试在新的major版本中实现降级支持。</li></ul></li><li><p><strong>升级状态字段讨论</strong></p><ul><li>讨论了升级状态字段的持久性和内容，以及如何改进以更好地支持降级。</li><li>结果建议在升级完成后保留升级状态信息，并提供清除命令。</li></ul></li><li><p><strong>格式标志问题</strong></p><ul><li>讨论了命令行中的<code>--format</code>标志存在的问题，即无论指定何种格式，总是返回JSON。</li><li>结果提出了使用装饰器来处理格式转换，并确保支持的格式类型明确。</li></ul></li><li><p><strong>NFS相关问题</strong></p><ul><li>讨论了NFS的高可用性和扩展性问题，特别是在Ceph和Rook中的实现差异。</li><li>结果讨论了NFS demon的故障转移、主机离线检测和处理策略，以及NFS服务的配置和管理。</li></ul></li></ol><h3 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h3><ul><li>继续测试和评估minor版本降级的可行性。</li><li>在新的major版本中尝试实现降级支持，并引入强制标志。</li><li>实现升级状态信息的持久化，并提供清除命令。</li><li>进行实验性实现格式标志问题，并在后续会议中展示结果。</li><li>继续研究和测试NFS的高可用性和扩展性解决方案。</li></ul><h3 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h3><ul><li>会议于具体时间结束，下次会议预定于具体时间。</li></ul>',10)])])}const u=a(r,[["render",o]]);export{_ as __pageData,u as default};
